        asset_type_infra: "உள்கட்டமைப்பு", asset_type_machinery: "இயந்திரங்கள்", asset_drip: "சொட்டு நீர் பாசனம்", asset_drip_desc: "தண்ணீரை சேமிக்கிறது. வறட்சியிலிருந்து பாதுகாக்கிறது.", asset_tractor: "பவர் டில்லர்", asset_tractor_desc: "உழைப்பு செலவை குறைக்கிறது.", asset_greenhouse: "பாலிஹவுஸ் வலை", asset_greenhouse_desc: "பூச்சிகளிலிருந்து பாதுகாக்கிறது.", asset_solar: "சூரிய பம்ப்", asset_solar_desc: "இலவச மின்சாரம்.", asset_warehouse: "கிடங்கு", asset_warehouse_desc: "பயிர்களை பாதுகாப்பாக சேமிக்கவும்.",
