        mandi_local: "உள்ளூர் கிராம APMC", mandi_local_desc: "உங்கள் கிராமத்திலேயே விற்கவும். போக்குவரத்து செலவு இல்லை.", mandi_district: "மாவட்ட பிரதான மண்டி", mandi_district_desc: "ஒரு சிறிய லாரியை வாடகைக்கு எடுக்கவும். விலை மற்றும் செலவு இடையே நல்ல சமநிலை.", mandi_state: "மாநில வேளாண் சந்தை", mandi_state_desc: "கனரக போக்குவரத்தை வாடகைக்கு எடுக்கவும். அதிக விலை, அதிக கட்டணம்.",
        sch_info: "அரசு திட்டங்களுக்கு விண்ணப்பிப்பது இலவசம். இவை நிதி பாதுகாப்பை வழங்குகின்றன.", sch_eligibility: "தகுதி", sch_benefit: "நன்மை", sch_enrolled: "பதிவுசெய்யப்பட்டு செயலில் உள்ளது", sch_apply: "இப்போதே விண்ணப்பிக்கவும்", sch_not_eligible: "தகுதியில்லை", sch_all_e: "அனைத்து விவசாயிகளுக்கும் தகுதி உண்டு.",
        sch_pmkisan_n: "PM-கிசான் திட்டம்", sch_pmkisan_d: "விவசாயிகளுக்கு வருமான ஆதரவை வழங்கும் நேரடி நன்மை பரிமாற்றம் (DBT).", sch_pmkisan_b: "ஒரு பருவத்திற்கு ₹2,000 நேரடியாக வங்கி கணக்கில் கிடைக்கும்.", sch_pmkisan_e: "5 ஏக்கர் அல்லது அதற்கும் குறைவான நிலம் இருக்க வேண்டும்.",
        sch_pmfby_n: "PMFBY பயிர் காப்பீடு", sch_pmfby_d: "இயற்கை பேரழிவுகளிலிருந்து பாதுகாக்கிறது.", sch_pmfby_b: "பயிர் காப்பீட்டு பிரீமியத்தை 50% குறைக்கிறது.",
        sch_miss_n: "MISS (வட்டி மானியம்)", sch_miss_d: "குறுகிய கால விவசாய கடன்களுக்கான வட்டி மானியத் திட்டம்.", sch_miss_b: "KCC கடன் வட்டி விகிதத்தை 7% இலிருந்து 4% ஆக குறைக்கிறது.", sch_miss_e: "600+ கடன் மதிப்பெண் தேவை.",
        sch_soil_n: "மண் வள அட்டை", sch_soil_d: "பயிருக்குத் தேவையான உரப் பரிந்துரைகளை வழங்குகிறது.", sch_soil_b: "பயிர் இடுபொருள் செலவை 10% குறைக்கிறது.",
        sch_enam_n: "இ-நாம் (e-NAM)", sch_enam_d: "விவசாயிகளை வாங்குபவர்களுடன் டிஜிட்டல் முறையில் இணைக்கிறது.", sch_enam_b: "பயிர் விற்பனை விலையை 10% அதிகரிக்கிறது.",
        sch_kusum_n: "PM-KUSUM மானியம்", sch_kusum_d: "சூரிய ஒளி பாசனத்திற்கான அரசு மானியத் திட்டம்.", sch_kusum_b: "சூரிய பம்ப் வாங்கும்போது மூலதன செலவில் 50% தள்ளுபடி.",
        sch_drop_n: "பெர் ட்ராப் மோர் க்ராப்", sch_drop_d: "நுண்ணீர் பாசனத்தை ஊக்குவிக்கிறது.", sch_drop_b: "சொட்டு நீர் பாசனம் வாங்கும்போது 50% தள்ளுபடி.",
        sch_smam_n: "SMAM (இயந்திரமயமாக்கல்)", sch_smam_d: "இயந்திரங்களை மலிவாக வழங்கும் திட்டம்.", sch_smam_b: "மினி டிராக்டர் வாங்கும்போது 50% தள்ளுபடி.",
        evt_fraud_title: "OTP மோசடி அழைப்பு", evt_fraud_desc: "வங்கி மேலாளர் என்று கூறி OTP கேட்கிறார்கள்.", evt_fraud_a: "அழைப்பைத் துண்டித்து பிளாக் செய்", evt_fraud_b: "OTP-யைப் பகிர்",
        evt_seeds_title: "மோசமான முளைப்பு", evt_seeds_desc: "விதைகள் சரியாக முளைக்கவில்லை.", evt_seeds_a: "மீண்டும் விதைக்க", evt_seeds_b: "காத்திரு",
        evt_monsoon_title: "பருவமழை தாமதம்", evt_monsoon_desc: "மழை தாமதமாகிறது. மண் வறண்டு போகிறது.", evt_monsoon_a: "தண்ணீர் லாரி வாடகைக்கு எடு", evt_monsoon_b: "மழையை நம்பியிரு",
        evt_theft_title: "பண ஆபத்து", evt_theft_desc: "உரத்திற்காக பெருமளவு பணத்தை எடுத்துச் செல்வது ஆபத்தானது.", evt_theft_a: "UPI மூலம் செலுத்து", evt_theft_b: "பணமாக செலுத்து",
        evt_pest_title: "பூச்சி தாக்குதல்", evt_pest_desc: "பூச்சிகள் பயிரை சேதப்படுத்துகின்றன.", evt_pest_a: "பூச்சிக்கொல்லி மருந்து தெளிக்க", evt_pest_b: "வீட்டு வைத்தியம்",
