interface LanguageContextType {
    language: Language;
    setLanguage: (lang: Language) => void;
    t: (key: string, values?: Record<string, string | number>) => string; 
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export const LanguageProvider = ({ children }: { children: ReactNode }) => {
    const [language, setLanguageState] = useState<Language>('en');

    useEffect(() => {
        const savedLang = localStorage.getItem('krishiniti_lang') as Language;
        if (savedLang && (translations as any)[savedLang]) {
            setLanguageState(savedLang);
        }
    }, []);

    const setLanguage = (lang: Language) => {
        setLanguageState(lang);
        localStorage.setItem('krishiniti_lang', lang);
    };

    const t = (key: string, values?: Record<string, string | number>): string => {
        let str = (translations[language] as any)[key] || (translations['en'] as any)[key] || key;
        
        if (values && typeof str === 'string') {
            Object.keys(values).forEach(v => {
                str = str.replace(new RegExp(`{${v}}`, 'g'), values[v].toString());
            });
        }
        return str;
    };

    return (
        <LanguageContext.Provider value={{ language, setLanguage, t }}>
            {children}
        </LanguageContext.Provider>
    );
};

export const useLanguage = () => {
    const context = useContext(LanguageContext);
    if (!context) throw new Error("useLanguage must be used within LanguageProvider");
    return context;
};